def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    # Allow None to be passed through unchanged
    if value is None:
        return None

    # Verify that the value is a datetime.time instance
    # We avoid importing datetime by checking the type's module and name
    if not (type(value).__module__ == 'datetime' and type(value).__name__ == 'time'):
        raise TypeError(f"Expected a datetime.time instance, got {type(value).__name__}")

    # Convert the time to an ISO 8601 string representation
    try:
        return value.isoformat()
    except Exception as exc:
        raise ValueError(f"Failed to dehydrate time value: {exc}") from exc

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    try:
        if value is None:
            return None
        # Attempt to extract coordinates from attributes
        coords = {}
        for attr in ('x', 'y', 'z'):
            if hasattr(value, attr):
                coords[attr] = getattr(value, attr)
        if coords:
            return coords
        # Fallback: if value is a sequence (tuple or list)
        if isinstance(value, (tuple, list)):
            if len(value) >= 2:
                coords['x'] = value[0]
                coords['y'] = value[1]
                if len(value) > 2:
                    coords['z'] = value[2]
                return coords
        # If we reach here, the input is not a supported Point representation
        raise TypeError("Unsupported Point type")
    except Exception as e:
        raise ValueError(f"Error dehydrating point: {e}") from e

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    # Ensure we are working with a valid instance
    if self is None:
        raise ValueError("Instance is None, cannot retrieve keys.")
    try:
        # Prefer a dedicated data attribute if present
        if hasattr(self, "data") and isinstance(getattr(self, "data"), dict):
            return list(self.data.keys())
        # Fallback to the instance's __dict__ if no explicit data attribute
        if hasattr(self, "__dict__"):
            return list(self.__dict__.keys())
        # If neither is available, raise an informative error
        raise AttributeError("No suitable data container found on the instance.")
    except Exception as exc:
        # Wrap any unexpected exception in a RuntimeError for clarity
        raise RuntimeError(f"Failed to retrieve keys: {exc}") from exc

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Validate the protocol_version argument
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple or None")

        # Retrieve the mapping of supported protocol handlers.
        # The class is expected to define a class attribute named
        # `_protocol_handlers` that maps version tuples to handler classes.
        try:
            handlers = getattr(cls, "_protocol_handlers", {})
            if not isinstance(handlers, dict):
                # If the attribute exists but is not a dict, treat as empty.
                handlers = {}
        except Exception:
            # Any unexpected error retrieving the mapping results in an empty dict.
            handlers = {}

        # If a specific protocol version was requested, return a dict
        # containing only that version if it is supported.
        if protocol_version is not None:
            handler = handlers.get(protocol_version)
            return {protocol_version: handler} if handler is not None else {}

        # No specific version requested; return a copy of all supported handlers.
        return dict(handlers)

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Attempt to find the key in a list-like attribute named 'items'
    try:
        if hasattr(self, 'items'):
            return self.items.index(key)
    except Exception:
        # If 'items' is not a list or the key is not present, ignore and try next
        pass

    # Attempt to find the key in a dict-like attribute named 'data'
    try:
        if hasattr(self, 'data'):
            return list(self.data.keys()).index(key)
    except Exception:
        # If 'data' is not a dict or the key is not present, ignore and try next
        pass

    # If the key was not found in any known structure, raise an informative error
    raise ValueError(f"Key {key!r} not found in the container")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Ensure the object behaves like a mapping
    if not hasattr(self, "items") or not hasattr(self, "__getitem__"):
        raise TypeError("Object does not support mapping interface")

    # If no keys are provided, return all values
    if not keys:
        try:
            return list(self.values())
        except Exception as exc:
            raise RuntimeError("Failed to retrieve all values") from exc

    # Prepare list of items for index-based access
    try:
        items = list(self.items())
    except Exception as exc:
        raise RuntimeError("Failed to retrieve items for indexing") from exc

    result = []
    for key in keys:
        if isinstance(key, int):
            # Index-based access
            try:
                result.append(items[key][1])
            except IndexError as exc:
                raise IndexError(f"Index {key} out of range for record values") from exc
        else:
            # Key-based access
            try:
                result.append(self[key])
            except KeyError as exc:
                raise KeyError(f"Key {key!r} not found in record") from exc
            except TypeError as exc:
                # Key is not hashable
                raise KeyError(f"Key {key!r} is not hashable") from exc
    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
        """
        Appends a DISCARD message to the output queue.

        :param n: number of records to discard, default = -1 (ALL)
        :param qid: query ID to discard for, default = -1 (last query)
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        """
        # Validate numeric parameters
        if not isinstance(n, int):
            raise TypeError(f"n must be an int, got {type(n).__name__}")
        if not isinstance(qid, int):
            raise TypeError(f"qid must be an int, got {type(qid).__name__}")

        # Normalize hooks
        dehydration_hooks = dehydration_hooks or {}
        hydration_hooks = hydration_hooks or {}

        # Validate hooks
        for hooks, name in ((dehydration_hooks, "dehydration_hooks"),
                            (hydration_hooks, "hydration_hooks")):
            if not isinstance(hooks, dict):
                raise TypeError(f"{name} must be a dict, got {type(hooks).__name__}")
            for typ, func in hooks.items():
                if not isinstance(typ, type):
                    raise TypeError(f"Key in {name} must be a type, got {type(typ).__name__}")
                if not callable(func):
                    raise TypeError(f"Value for type {typ.__name__} in {name} must be callable")

        # Validate handlers
        for key, func in handlers.items():
            if not callable(func):
                raise TypeError(f"Handler for '{key}' must be callable, got {type(func).__name__}")

        # Construct the message
        message = {
            "type": "DISCARD",
            "n": n,
            "qid": qid,
            "dehydration_hooks": dehydration_hooks,
            "hydration_hooks": hydration_hooks
        }

        # Append to the output queue
        try:
            self._out_queue.append(message)
        except AttributeError as exc:
            raise RuntimeError("Output queue not initialized on this instance") from exc
        except Exception as exc:
            raise RuntimeError("Failed to append DISCARD message to output queue") from exc

        # Return a Response object with the provided handlers
        try:
            return Response(**handlers)
        except Exception as exc:
            raise RuntimeError("Failed to create Response object") from exc

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate mode
    if mode is not None and mode not in ("READ", "WRITE"):
        raise ValueError("mode must be 'READ' or 'WRITE'")

    # Validate bookmarks
    if bookmarks is not None:
        try:
            iter(bookmarks)
        except TypeError:
            raise TypeError("bookmarks must be an iterable")

    # Validate metadata
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("metadata must be a dictionary")

    # Validate timeout
    if timeout is not None and not isinstance(timeout, (int, float)):
        raise TypeError("timeout must be a number")

    # Validate db
    if db is not None and not isinstance(db, str):
        raise TypeError("db must be a string")

    # Validate imp_user
    if imp_user is not None and not isinstance(imp_user, str):
        raise TypeError("imp_user must be a string")

    # Validate dehydration_hooks
    if dehydration_hooks is not None:
        if not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dict")
        for key, val in dehydration_hooks.items():
            if not isinstance(key, type):
                raise TypeError("dehydration_hooks keys must be types")
            if not callable(val):
                raise TypeError("dehydration_hooks values must be callables")

    # Validate hydration_hooks
    if hydration_hooks is not None:
        if not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dict")
        for key, val in hydration_hooks.items():
            if not isinstance(key, type):
                raise TypeError("hydration_hooks keys must be types")
            if not callable(val):
                raise TypeError("hydration_hooks values must be callables")

    # Build options dictionary
    options = {}
    if mode is not None:
        options["mode"] = mode
    if bookmarks is not None:
        options["bookmarks"] = list(bookmarks)
    if metadata is not None:
        options["metadata"] = metadata
    if timeout is not None:
        options["timeout"] = timeout
    if db is not None:
        options["db"] = db
    if imp_user is not None:
        options["imp_user"] = imp_user

    # Append BEGIN message to the output queue
    try:
        self._output_queue.append(("BEGIN", options))
    except AttributeError:
        # Fallback to a generic queue attribute if present
        if hasattr(self, "queue"):
            self.queue.append(("BEGIN", options))
        else:
            raise RuntimeError("No output queue available to append BEGIN message")

    # Return a Response object with the provided handlers
    return Response(self, handlers)

