def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    # Validate parameters
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise TypeError("maxsize must be a positive integer")
    if not isinstance(ttl, (int, float)) or ttl < 0:
        raise TypeError("ttl must be a non-negative number")
    if not callable(timer):
        raise TypeError("timer must be a callable returning a monotonic time")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a boolean")

    def decorator(func):
        cache = {}
        order = []

        def wrapper(*args, **kwargs):
            try:
                key_args = args
                key_kwargs = tuple(sorted(kwargs.items()))
                if typed:
                    key = (key_args, key_kwargs,
                           tuple(type(arg) for arg in args),
                           tuple(type(v) for v in kwargs.values()))
                else:
                    key = (key_args, key_kwargs)

                now = timer()
                if key in cache:
                    value, expire = cache[key]
                    if expire > now:
                        # Move key to end to mark as recently used
                        try:
                            order.remove(key)
                        except ValueError:
                            pass
                        order.append(key)
                        return value
                    else:
                        # Expired entry
                        del cache[key]
                        try:
                            order.remove(key)
                        except ValueError:
                            pass

                # Compute new value
                result = func(*args, **kwargs)
                expire_time = now + ttl
                cache[key] = (result, expire_time)
                order.append(key)

                # Evict least recently used if over maxsize
                if len(order) > maxsize:
                    lru_key = order.pop(0)
                    cache.pop(lru_key, None)

                return result
            except Exception as exc:
                # Re-raise any exception from timer or function
                raise exc

        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__module__ = func.__module__
        wrapper.__dict__.update(func.__dict__)
        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    if maxsize is not None and maxsize < 0:
        maxsize = 0

    def decorator(func):
        cache = {}
        order = []

        def make_key(args, kwargs):
            # Build a hashable key from args and kwargs
            key_parts = []
            for arg in args:
                if typed:
                    key_parts.append((arg, type(arg)))
                else:
                    key_parts.append(arg)
            # For kwargs, sort by key to ensure consistent order
            if kwargs:
                for k in sorted(kwargs):
                    v = kwargs[k]
                    if typed:
                        key_parts.append((k, v, type(v)))
                    else:
                        key_parts.append((k, v))
            return tuple(key_parts)

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            if key in cache:
                # Move key to the end to mark it as recently used
                try:
                    order.remove(key)
                except ValueError:
                    pass
                order.append(key)
                return cache[key]
            # Compute the result
            result = func(*args, **kwargs)
            # Store in cache
            cache[key] = result
            order.append(key)
            # Evict least recently used if needed
            if maxsize is not None and len(order) > maxsize:
                oldest = order.pop(0)
                cache.pop(oldest, None)
            return result

        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        first_key = next(iter(self))
    except StopIteration:
        raise KeyError("popitem(): dictionary is empty")
    value = self.pop(first_key)
    return (first_key, value)

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        if key in self:
            return self[key]
    except TypeError as exc:
        # key is unhashable or other lookup error
        raise TypeError(f"Unhashable or invalid key {key!r}") from exc
    try:
        self[key] = default
    except Exception as exc:
        # propagate assignment errors (e.g., read-only mapping)
        raise ValueError(f"Failed to set key {key!r} to {default!r}") from exc
    return default

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default
    except Exception:
        # In case self is not subscriptable or other unexpected errors
        return default

def is_file_exist(file_name):
        """
        Check if file name exist.
        :param file_name: File name.
        :type file_name: str
        :return: Return true (exist), false (do not exist, or invalid file name)
        :rtype bool
        """
        # Validate input type
        if not isinstance(file_name, str):
            return False
        # Empty string or whitespace-only is considered invalid
        if not file_name.strip():
            return False
        try:
            import os
            return os.path.isfile(file_name)
        except Exception:
            # Any exception (e.g., permission error, invalid path) results in False
            return False

def _reset_logging(cls):
    """
    Reset
    """
    try:
        logging.shutdown()
        for handler in logging.root.handlers[:]:
            logging.root.removeHandler(handler)
        logging.basicConfig()
    except NameError:
        # logging module not available
        return
    except Exception:
        # ignore other errors
        return

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """
    Return attribute names and descriptions defined by the interface.

    Parameters
    ----------
    all : bool, optional
        If True, include all attributes of the instance; otherwise, only
        those explicitly defined by the interface (i.e., those listed in
        the class variable `_attributes` or `_descriptions`).

    Returns
    -------
    list of tuple
        Each tuple contains (attribute_name, description).  The list is
        sorted alphabetically by attribute name.
    """
    # Validate the `all` argument
    if not isinstance(all, bool):
        raise TypeError("'all' must be a boolean value")

    # Determine the set of attribute names to consider
    if all:
        # Include every attribute that is not private or a method
        candidate_names = set(dir(self))
    else:
        # Prefer explicit interface definitions if available
        candidate_names = set()
        cls = self.__class__
        if hasattr(cls, "_attributes"):
            try:
                candidate_names.update(cls._attributes)
            except Exception:
                pass
        if hasattr(cls, "_descriptions"):
            # `_descriptions` may be a dict mapping names to descriptions
            try:
                candidate_names.update(cls._descriptions.keys())
            except Exception:
                pass
        # If no explicit interface is defined, fall back to all attributes
        if not candidate_names:
            candidate_names = set(dir(self))

    # Prepare the result list
    result = []

    for name in sorted(candidate_names):
        # Skip private attributes and methods
        if name.startswith("_"):
            continue
        try:
            attr = getattr(self, name)
        except Exception:
            # Skip attributes that cannot be accessed
            continue
        if callable(attr):
            continue

        # Attempt to obtain a description
        description = None
        cls = self.__class__

        # 1. Check if the class defines a `_descriptions` mapping
        if hasattr(cls, "_descriptions"):
            try:
                description = cls._descriptions.get(name)
            except Exception:
                pass

        # 2. If still None, try to get the docstring from a property
        if description is None:
            try:
                prop = getattr(cls, name)
                if isinstance(prop, property):
                    description = prop.fget.__doc__
            except Exception:
                pass

        result.append((name, description))

    return result

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        return not _c_optimizations_required()
    except Exception:
        return False

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        # If PURE_PYTHON is truthy, we are running in pure Python mode and
        # C optimizations are not required.  Otherwise, they are required.
        return not bool(PURE_PYTHON)
    except NameError:
        # If PURE_PYTHON is not defined, assume C optimizations are needed.
        return True

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the current context
    try:
        self._context = {}
    except AttributeError:
        # If the attribute does not exist, create it
        self._context = {}

    # Reinitialize bins
    # Prefer the initial_value if it was provided during construction.
    # Otherwise, fall back to the make_bins callable if available.
    if hasattr(self, "_initial_value") and self._initial_value is not None:
        try:
            # Attempt a shallow copy; if that fails, use deepcopy
            self._bins = dict(self._initial_value)
        except Exception:
            try:
                import copy
                self._bins = copy.deepcopy(self._initial_value)
            except Exception:
                # As a last resort, just assign the original reference
                self._bins = self._initial_value
    else:
        # No initial_value; try to use make_bins if it exists and is callable
        if hasattr(self, "_make_bins") and callable(self._make_bins):
            try:
                self._bins = self._make_bins()
            except Exception:
                # If make_bins fails, fall back to an empty dict
                self._bins = {}
        else:
            # No make_bins; default to an empty dict
            self._bins = {}

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate the coordinate name
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    if not coord_name:
        raise ValueError("coord_name must not be empty")

    # Determine which attribute holds the mapping
    mapping = None
    if hasattr(self, "_coord_err_map"):
        mapping = self._coord_err_map
    elif hasattr(self, "_err_indices"):
        mapping = self._err_indices
    else:
        raise AttributeError(
            "The object does not have an error indices mapping attribute"
        )

    # Retrieve the indices for the given coordinate
    try:
        indices = mapping[coord_name]
    except KeyError:
        raise KeyError(f"No error indices found for coordinate '{coord_name}'")

    # Ensure the result is iterable and return a copy
    try:
        return list(indices)
    except TypeError:
        raise TypeError(
            f"Error indices for coordinate '{coord_name}' must be iterable"
        )

