def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        run_attr = getattr(obj, 'run')
    except Exception:
        return False
    return callable(run_attr)

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return (
            hasattr(obj, "fill")
            and callable(getattr(obj, "fill"))
            and hasattr(obj, "compute")
            and callable(getattr(obj, "compute"))
        )
    except Exception:
        return False

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Convert coordinate to a NumPy array for easier handling
    try:
        coord_arr = np.asarray(coord)
    except Exception:
        raise TypeError("coord must be array-like")

    # Ensure the coordinate is one‑dimensional and matches the histogram dimensionality
    if coord_arr.ndim != 1:
        raise ValueError("coord must be a one‑dimensional sequence")
    if coord_arr.size != self.ndim:
        raise ValueError(f"coord must have length {self.ndim}")

    # Check that the coordinate lies within the histogram bounds
    for i, val in enumerate(coord_arr):
        edges = self.edges[i]
        if val < edges[0] or val >= edges[-1]:
            # Outside the histogram edges – ignore this entry
            return

    # Find the bin indices for each dimension
    try:
        idx = np.searchsorted(self.edges, coord_arr, side='right') - 1
    except Exception as e:
        raise RuntimeError(f"Error computing bin indices: {e}")

    # Ensure indices are valid (should be true given the bounds check)
    if np.any(idx < 0) or np.any(idx >= [len(e) - 1 for e in self.edges]):
        return

    # Increment the histogram bin by the specified weight
    try:
        self.hist[tuple(idx)] += weight
    except Exception as e:
        raise RuntimeError(f"Failed to increment histogram bin: {e}")

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    # Ensure labels is a dictionary
    if not isinstance(labels, dict):
        raise TypeError(f"labels must be a dict, got {type(labels).__name__}")

    errors = []

    # Helper to check regex match
    def _match_regex(value, pattern, label_type):
        try:
            # Use fullmatch to ensure entire string matches
            return pattern.fullmatch(value) is not None
        except Exception:
            # If pattern is not a compiled regex, try compiling
            import re
            try:
                compiled = re.compile(pattern)
                return compiled.fullmatch(value) is not None
            except Exception:
                return False

    # Assume LABEL_KEY_REGEX and LABEL_VALUE_REGEX are defined elsewhere
    try:
        key_pattern = LABEL_KEY_REGEX
    except NameError:
        import re
        key_pattern = re.compile(r"^[a-zA-Z0-9._-]+$")  # default pattern
    try:
        value_pattern = LABEL_VALUE_REGEX
    except NameError:
        import re
        value_pattern = re.compile(r"^[a-zA-Z0-9._-]+$")  # default pattern

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): "expected string or bytes-like object"})
        else:
            # Convert bytes to str for regex matching
            key_str = key.decode() if isinstance(key, bytes) else key
            if not _match_regex(key_str, key_pattern, "key"):
                errors.append({key_str: f"Label key '{key_str}' does not match the regex [{key_pattern.pattern}]"})
        # Validate value
        if not isinstance(value, (str, bytes)):
            errors.append({str(value): "expected string or bytes-like object"})
        else:
            value_str = value.decode() if isinstance(value, bytes) else value
            if not _match_regex(value_str, value_pattern, "value"):
                errors.append({value_str: f"Label value '{value_str}' does not match the regex [{value_pattern.pattern}]"})
    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from resource kind to its default observer schema.
    """
    try:
        # Safely access the manifest list
        spec = getattr(app, "spec", None)
        if spec is None:
            return {}

        manifest = getattr(spec, "manifest", None)
        if manifest is None or not isinstance(manifest, list):
            return {}

        # Start with any existing observer schema
        existing_schema = getattr(spec, "observer_schema", {})
        if existing_schema is None:
            existing_schema = {}
        # Make a copy so we don't mutate the original
        observer_schema = dict(existing_schema)

        for resource in manifest:
            if not isinstance(resource, dict):
                continue
            kind = resource.get("kind")
            if not kind:
                continue
            # Skip if a custom schema already exists for this kind
            if kind in observer_schema:
                continue
            api_version = resource.get("apiVersion")
            # Default schema: just include apiVersion and kind
            observer_schema[kind] = {"apiVersion": api_version, "kind": kind}

        return observer_schema
    except Exception as exc:
        # Wrap any unexpected error in a ValueError with context
        raise ValueError(f"Error generating default observer schema: {exc}") from exc

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Validate prefix type
    if prefix is None:
        prefix = ''
    if not isinstance(prefix, str):
        raise TypeError(f"prefix must be a string, got {type(prefix).__name__}")
    # Retrieve status attribute safely
    try:
        status = getattr(self, 'status')
    except AttributeError:
        status = None
    # Convert status to a readable string
    if status is None:
        status_repr = 'unknown'
    elif isinstance(status, bool):
        status_repr = 'valid' if status else 'invalid'
    elif isinstance(status, (list, tuple)):
        status_repr = ', '.join(str(item) for item in status)
    else:
        status_repr = str(status)
    return f"{prefix}{status_repr}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    try:
        if prefix is None:
            prefix = ''
        if not isinstance(prefix, str):
            raise TypeError("prefix must be a string")
        # Attempt to retrieve the validation log from common attribute names
        log = getattr(self, 'validation_log', None)
        if log is None:
            log = getattr(self, 'log', None)
        if log is None:
            log = getattr(self, 'validation_log_entries', None)
        if log is None:
            return ''
        if isinstance(log, (list, tuple)):
            return '\n'.join(prefix + str(item) for item in log)
        else:
            return prefix + str(log)
    except Exception:
        # In case of any unexpected error, return an empty string
        return ''

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type check
    if prior is None:
        raise ValueError("prior cannot be None")
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}")

    # Ensure both objects have a 'version' attribute
    if not hasattr(self, "version") or not hasattr(prior, "version"):
        raise AttributeError("Both inventories must have a 'version' attribute")

    # Version ordering: prior must be strictly older
    if prior.version >= self.version:
        raise ValueError(
            f"prior version ({prior.version}) must be less than current version ({self.version})"
        )

    # Optional: check that prior's inventory is a subset of the current inventory
    # This assumes an 'inventory' attribute that is dict-like or iterable of keys.
    if hasattr(self, "inventory") and hasattr(prior, "inventory"):
        try:
            # If inventory is a dict, iterate over keys
            if isinstance(self.inventory, dict) and isinstance(prior.inventory, dict):
                for key, val in prior.inventory.items():
                    if key not in self.inventory:
                        raise ValueError(
                            f"Item '{key}' present in prior inventory but missing in current inventory"
                        )
                    # Optional: ensure values are compatible (e.g., same or greater)
                    if self.inventory[key] != val:
                        # Depending on business rules, you might allow differences.
                        # Here we simply warn if values differ.
                        pass
            else:
                # If inventory is not dict, attempt to iterate over it
                for item in prior.inventory:
                    if item not in self.inventory:
                        raise ValueError(
                            f"Item '{item}' present in prior inventory but missing in current inventory"
                        )
        except Exception as exc:
            # Catch any unexpected errors during inventory comparison
            raise RuntimeError(f"Error validating inventory compatibility: {exc}") from exc

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inventory type
    if not isinstance(inventory, (dict, list)):
        raise TypeError("inventory must be a dict or list")

    result = {}

    # Helper to process a state dict
    def _process_state(state):
        if not isinstance(state, dict):
            return
        for logical_path, content_files in state.items():
            if logical_path is None:
                continue
            # Ensure we have an iterable of files
            if isinstance(content_files, (list, set, tuple)):
                files_iter = content_files
            else:
                # Treat non-iterable as a single file
                files_iter = (content_files,)
            try:
                for f in files_iter:
                    if f is None:
                        continue
                    result.setdefault(logical_path, set()).add(f)
            except TypeError:
                # content_files is not iterable; skip
                continue

    # Handle dict inventory: mapping version -> state
    if isinstance(inventory, dict):
        if version not in inventory:
            raise ValueError(f"Version {version} not found in inventory")
        # Sort versions lexicographically; this may not be perfect for numeric versions
        sorted_versions = sorted(inventory.keys())
        try:
            start_index = sorted_versions.index(version)
        except ValueError:
            raise ValueError(f"Version {version} not found in inventory")
        for v in sorted_versions[start_index:]:
            state = inventory.get(v)
            _process_state(state)
        return result

    # Handle list inventory
    if isinstance(inventory, list):
        # Case 1: list of dicts with 'version' and 'state' keys
        if all(isinstance(item, dict) and 'version' in item for item in inventory):
            try:
                start_index = next(i for i, item in enumerate(inventory) if item['version'] == version)
            except StopIteration:
                raise ValueError(f"Version {version} not found in inventory")
            for item in inventory[start_index:]:
                state = item.get('state')
                _process_state(state)
            return result

        # Case 2: list of tuples (version, state)
        if all(isinstance(item, tuple) and len(item) == 2 for item in inventory):
            try:
                start_index = next(i for i, (v, _) in enumerate(inventory) if v == version)
            except StopIteration:
                raise ValueError(f"Version {version} not found in inventory")
            for v, state in inventory[start_index:]:
                _process_state(state)
            return result

        # Unsupported list format
        raise TypeError("Unsupported inventory list format")

    # Should not reach here
    raise TypeError("Unsupported inventory type")

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Basic type checks
        if fixity is None:
            raise ValueError("Fixity block is missing.")
        if not isinstance(fixity, dict):
            raise ValueError(f"Fixity block must be a dictionary, got {type(fixity).__name__}.")

        if manifest_files is None:
            raise ValueError("Manifest files list is missing.")
        # Ensure manifest_files is an iterable of strings
        try:
            manifest_set = set(manifest_files)
        except TypeError:
            raise ValueError("Manifest files must be an iterable of file paths.")
        if not all(isinstance(f, str) for f in manifest_set):
            raise ValueError("All manifest file paths must be strings.")

        # Validate each entry in the fixity block
        import re
        hex_pattern = re.compile(r'^[0-9a-fA-F]+$')
        for path, hash_value in fixity.items():
            if not isinstance(path, str):
                raise ValueError(f"Fixity key {path!r} is not a string.")
            if not isinstance(hash_value, str):
                raise ValueError(f"Fixity value for {path!r} is not a string.")
            if path not in manifest_set:
                raise ValueError(f"Fixity references unknown file {path!r}.")
            if not hex_pattern.match(hash_value):
                raise ValueError(f"Hash value for {path!r} is not a valid hexadecimal string.")

        # Optionally, ensure that all files in the manifest are referenced in fixity
        # (not required by the docstring, but can be useful)
        # missing_in_fixity = manifest_set - set(fixity.keys())
        # if missing_in_fixity:
        #     raise ValueError(f"Files missing from fixity block: {', '.join(sorted(missing_in_fixity))}")

        return True

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
        Mapping from the XML basename to a list of file paths that share that basename.
    """
    import os

    # Validate input
    if not isinstance(folder, str):
        raise TypeError(f"folder must be a string, got {type(folder).__name__}")

    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder '{folder}' does not exist or is not a directory")

    packages = {}
    try:
        for entry in os.listdir(folder):
            full_path = os.path.join(folder, entry)
            if not os.path.isfile(full_path):
                continue  # skip directories or non-files

            name, ext = os.path.splitext(entry)
            ext_lower = ext.lower()

            if ext_lower == ".xml":
                # Start a new package group
                packages[name] = [full_path]
            else:
                # Add to existing group if XML counterpart exists
                if name in packages:
                    packages[name].append(full_path)
                else:
                    # No XML file found for this basename; ignore or log
                    pass
    except OSError as exc:
        raise RuntimeError(f"Error accessing folder '{folder}': {exc}") from exc

    return packages

def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    # Validate language key
    if not isinstance(lang, str) or not lang.strip():
        raise ValueError("lang must be a non-empty string")
    # Validate file path
    if not isinstance(file_path, str) or not file_path.strip():
        raise ValueError("file_path must be a non-empty string")
    # Optional: check that the file exists
    try:
        import os
        if not os.path.isfile(file_path):
            raise FileNotFoundError(f"File not found: {file_path}")
    except Exception as exc:
        # Re-raise any exception that occurs during the file check
        raise exc
    # Ensure the renditions dictionary exists
    if not hasattr(self, "renditions") or not isinstance(self.renditions, dict):
        self.renditions = {}
    # Add or update the rendition entry
    self.renditions[lang] = file_path

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        A dictionary where each key is the basename of an XML file (without extension)
        and each value is another dictionary mapping the full file names within the
        zip to their corresponding byte contents.
    """
    import os
    import zipfile

    # Validate input
    if not isinstance(zip_path, str):
        raise TypeError(f"zip_path must be a string, got {type(zip_path).__name__}")
    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"File not found: {zip_path}")

    packages = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for file_name in zf.namelist():
                # Skip directories
                if file_name.endswith('/'):
                    continue
                # Identify XML files (case-insensitive)
                if file_name.lower().endswith('.xml'):
                    base = os.path.splitext(os.path.basename(file_name))[0]
                    if base not in packages:
                        packages[base] = {}
                # For all files, if they share a base with an XML file, include them
                # Determine base by stripping extension
                base_candidate = os.path.splitext(os.path.basename(file_name))[0]
                if base_candidate in packages:
                    try:
                        content = zf.read(file_name)
                    except RuntimeError as e:
                        # Skip files that cannot be read
                        continue
                    packages[base_candidate][file_name] = content
    except zipfile.BadZipFile as e:
        raise ValueError(f"Invalid zip file: {zip_path}") from e
    except Exception as e:
        # Re-raise any other exception as a generic error
        raise RuntimeError(f"Error processing zip file {zip_path}") from e

    return packages

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    try:
        return content.replace('w:st="', 'w-st="')
    except Exception as exc:
        raise RuntimeError("Failed to replace namespace prefix") from exc

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    # Validate inputs
    if node is None or not pubdate_xpaths:
        return None

    for xpath in pubdate_xpaths:
        try:
            # Attempt to evaluate the XPath expression
            result = node.xpath(xpath)
            if result:
                first = result[0]
                # If the result is an element, return its text content
                if hasattr(first, "text"):
                    text = first.text
                    if text is not None:
                        return text.strip()
                # If the result is a string or other scalar, return it directly
                return str(first).strip()
        except Exception:
            # Ignore any errors from invalid XPath or evaluation issues
            continue

    # No match found
    return None

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Try importlib.metadata (Python 3.8+)
        try:
            from importlib.metadata import version, PackageNotFoundError
        except ImportError:
            # Fallback to pkg_resources for older Python versions
            try:
                import pkg_resources
                pkg_name = __package__ or __name__
                if pkg_name and pkg_name != "__main__":
                    return pkg_resources.get_distribution(pkg_name).version
            except Exception:
                pass
            raise
        pkg_name = __package__ or __name__
        if pkg_name and pkg_name != "__main__":
            return version(pkg_name)
    except Exception:
        # Return a default version string if anything goes wrong
        return "0.0.0"

def render(pieces, style):
    """Render the given version pieces into the requested style.

    Parameters
    ----------
    pieces : Iterable
        An iterable of version components (e.g., integers, strings, or other
        objects that can be converted to strings).  Non-iterable inputs raise
        a :class:`TypeError`.
    style : str
        The desired rendering style.  Supported styles are:

        * ``'dot'`` or ``'dot-separated'`` – join components with ``'.'``.
        * ``'dash'`` or ``'dash-separated'`` – join components with ``'-'``.
        * ``'underscore'`` or ``'underscore-separated'`` – join components with ``'_'``.
        * ``'json'`` – return a JSON array representation of the pieces.
        * ``'list'`` – return the Python list representation of the pieces.
        * ``'none'`` – return an empty string regardless of the pieces.

        Any other value raises a :class:`ValueError`.

    Returns
    -------
    str
        The rendered version string.

    Raises
    ------
    TypeError
        If ``pieces`` is not iterable.
    ValueError
        If ``style`` is not one of the supported styles.
    """
    # Validate pieces
    try:
        iterator = iter(pieces)
    except TypeError:
        raise TypeError("pieces must be an iterable of components") from None

    # Convert all pieces to strings, handling None gracefully
    try:
        component_strs = [str(p) for p in iterator]
    except Exception as exc:
        raise ValueError(f"Error converting pieces to strings: {exc}") from exc

    # Normalise style string
    if not isinstance(style, str):
        raise ValueError("style must be a string")
    style_key = style.strip().lower()

    # Mapping of style keys to joiners or handlers
    if style_key in {"dot", "dot-separated"}:
        return ".".join(component_strs)
    elif style_key in {"dash", "dash-separated"}:
        return "-".join(component_strs)
    elif style_key in {"underscore", "underscore-separated"}:
        return "_".join(component_strs)
    elif style_key == "json":
        import json
        return json.dumps(component_strs)
    elif style_key == "list":
        return str(component_strs)
    elif style_key == "none":
        return ""
    else:
        raise ValueError(f"Unsupported style '{style}'. "
                         f"Supported styles: dot, dash, underscore, json, list, none.")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    # Validate input
    if pieces is None:
        raise ValueError("Input cannot be None")
    if not isinstance(pieces, (list, tuple, set, str)):
        raise TypeError("Input must be a list, tuple, set, or string")
    # If it's a string, treat each character as a piece
    if isinstance(pieces, str):
        iterable = pieces
    else:
        iterable = pieces
    # Check for existing '+'
    try:
        for item in iterable:
            if item == '+':
                return '.'
    except Exception as e:
        # If iteration fails, raise a descriptive error
        raise TypeError(f"Unable to iterate over input: {e}") from e
    # No '+' found
    return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    # Build the command list
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        cmd = [commands]
    if args:
        if not isinstance(args, (list, tuple)):
            raise TypeError("args must be a list or tuple of arguments")
        cmd.extend(args)
    # Prepare stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else None
    try:
        if verbose:
            print(f"Running command: {' '.join(cmd)}")
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            stderr=stderr,
        )
        if verbose:
            print(f"Return code: {result.returncode}")
            print(f"Stdout: {result.stdout}")
            if not hide_stderr:
                print(f"Stderr: {result.stderr}")
        if result.returncode != 0:
            raise subprocess.CalledProcessError(
                result.returncode, cmd, output=result.stdout, stderr=result.stderr
            )
        return result.stdout
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {commands}") from e
    except OSError as e:
        raise RuntimeError(f"Error running command: {commands}") from e
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Command '{' '.join(cmd)}' failed with return code {e.returncode}") from e

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        return {}

    # Determine the base path where version directories reside
    base_path = getattr(self, "base_path", os.getcwd())

    # Load the root inventory if it hasn't been loaded yet
    if not hasattr(self, "root_inventory") or self.root_inventory is None:
        root_inv_path = os.path.join(base_path, "inventory.json")
        if not os.path.isfile(root_inv_path):
            raise FileNotFoundError(f"Root inventory file not found at {root_inv_path}")
        try:
            with open(root_inv_path, "r", encoding="utf-8") as f:
                self.root_inventory = json.load(f)
        except Exception as exc:
            raise RuntimeError(f"Failed to load root inventory: {exc}")

    # Dictionary to record differences: {file_path: [list_of_versions_with_diff]}
    differences = {}

    for ver in version_dirs:
        inv_path = os.path.join(base_path, ver, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory file missing for version '{ver}' at {inv_path}")

        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inv = json.load(f)
        except Exception as exc:
            raise RuntimeError(f"Failed to load inventory for version '{ver}': {exc}")

        # Compare each file's digest against the root inventory
        for file_path, digest in inv.items():
            root_digest = self.root_inventory.get(file_path)
            if root_digest is None or digest != root_digest:
                differences.setdefault(file_path, []).append(ver)

    # Store the differences for later validation steps
    self.different_digests = differences
    return differences

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to determine if a node is a MappingNode-like (has a list of key/value tuples)
    def is_mapping_node(node):
        try:
            return hasattr(node, 'value') and isinstance(node.value, list) and all(
                isinstance(pair, tuple) and len(pair) == 2 for pair in node.value
            )
        except Exception:
            return False

    if not isinstance(nodes, list):
        raise ValueError('nodes must be a list of (key_node, value_node) tuples')

    merged = {}
    order = []

    for item in nodes:
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError('each item in nodes must be a tuple of (key_node, value_node)')
        key_node, value_node = item
        if not hasattr(key_node, 'value'):
            raise ValueError('key_node must have a value attribute')
        key = key_node.value

        if key in merged:
            existing_key_node, existing_value_node = merged[key]
            # If both values are mapping nodes, deep merge them
            if is_mapping_node(existing_value_node) and is_mapping_node(value_node):
                # Merge the two lists of key/value pairs
                merged_pairs = existing_value_node.value + value_node.value
                # Recursively merge the combined list
                merged_value = existing_value_node.__class__(
                    tag=getattr(existing_value_node, 'tag', None),
                    value=deep_merge_nodes(merged_pairs)
                )
                merged[key] = (existing_key_node, merged_value)
            else:
                # Last value wins
                merged[key] = (key_node, value_node)
        else:
            merged[key] = (key_node, value_node)
            order.append(key)

    # Preserve original order of first appearance
    result = [(merged[k][0], merged[k][1]) for k in order]
    return result

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Validate that the input is an ArgumentParser-like object
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("parser must be an argparse.ArgumentParser instance")

    flags = []
    for action in actions:
        # Some actions may not have option_strings (e.g., positional arguments)
        try:
            flags.extend(action.option_strings)
        except AttributeError:
            continue

    return ' '.join(flags)

def make_parsers():
    '''
    Build a top-level parser and its subparsers and return them as a tuple.
    '''
    try:
        parser = argparse.ArgumentParser(description='Top-level parser')
    except NameError:
        raise ImportError('argparse module is required for make_parsers')
    subparsers = parser.add_subparsers(dest='command', required=True)
    return parser, subparsers

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to determine if a node is a MappingNode
    def is_mapping_node(node):
        return hasattr(node, 'value') and isinstance(node.value, list)

    # Merge two MappingNodes: node1 is the base, node2 is merged into node1
    def merge_mapping_nodes(node1, node2):
        # Build index map for node1's keys
        key_to_index = {}
        for idx, (k, _) in enumerate(node1.value):
            key_to_index[k.value] = idx
        # Iterate over node2's key-value pairs
        for k2, v2 in node2.value:
            key_str = k2.value
            if key_str in key_to_index:
                idx = key_to_index[key_str]
                _, existing_v = node1.value[idx]
                if is_mapping_node(existing_v) and is_mapping_node(v2):
                    # Recursively merge nested mappings
                    merge_mapping_nodes(existing_v, v2)
                else:
                    # Replace with the new value
                    node1.value[idx] = (k2, v2)
            else:
                # Append new key-value pair
                node1.value.append((k2, v2))
                key_to_index[key_str] = len(node1.value) - 1
        return node1

    # Validate input
    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list')
    result = []
    key_to_index = {}
    for entry in nodes:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise ValueError('each node must be a tuple of (key, value)')
        key_node, value_node = entry
        if not hasattr(key_node, 'value'):
            raise ValueError('key node must have a value attribute')
        key_str = key_node.value
        if key_str in key_to_index:
            idx = key_to_index[key_str]
            _, existing_value = result[idx]
            if is_mapping_node(existing_value) and is_mapping_node(value_node):
                merge_mapping_nodes(existing_value, value_node)
            else:
                # Replace with the new value
                result[idx] = (key_node, value_node)
        else:
            result.append((key_node, value_node))
            key_to_index[key_str] = len(result) - 1
    return result

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Validate that the input has the expected structure
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("parser must be an argparse.ArgumentParser instance")

    flags = []
    for action in actions:
        # Some actions (e.g., positional arguments) may not have option_strings
        option_strings = getattr(action, "option_strings", None)
        if option_strings:
            flags.extend(option_strings)

    return " ".join(flags)

def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    # Attempt to import argcomplete, which provides a convenient way to generate
    # bash completion scripts from an argparse parser.
    try:
        import argcomplete
    except ImportError:
        return (
            "# argcomplete is not installed. Install it with:\n"
            "#   pip install argcomplete\n"
            "# Then run this function again to generate the completion script."
        )

    # Import the function that returns the top‑level argparse parser for borgmatic.
    try:
        from borgmatic.cli import get_parser
    except Exception as exc:
        return f"# Failed to import borgmatic CLI parser: {exc}"

    # Generate the completion script using argcomplete.
    try:
        parser = get_parser()
        script = argcomplete.get_completion_script("borgmatic", parser)
        return script
    except Exception as exc:
        return f"# Error generating completion script: {exc}"

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Basic validation
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError('unparsed_arguments must be a list or tuple of strings')
    if not isinstance(subparsers, dict):
        raise TypeError('subparsers must be a dict mapping names to ArgumentParser instances')

    parsed = {}
    remaining_lists = []

    for name, parser in subparsers.items():
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f'Subparser for "{name}" does not have parse_known_args method')
        try:
            ns, remaining = parser.parse_known_args(list(unparsed_arguments))
        except Exception as exc:
            raise ValueError(f'Error parsing arguments for subparser "{name}": {exc}') from exc
        parsed[name] = ns
        remaining_lists.append(remaining)

    # Determine arguments not claimed by any subparser
    if remaining_lists:
        # Intersection of all remaining lists
        remaining_set = set(remaining_lists[0])
        for rem in remaining_lists[1:]:
            remaining_set &= set(rem)
    else:
        # No subparsers: all arguments are remaining
        remaining_set = set(unparsed_arguments)

    # Preserve original order
    remaining_args = [arg for arg in unparsed_arguments if arg in remaining_set]

    return parsed, remaining_args

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        raise TypeError("size must be a string")
    size = size.strip()
    if not size:
        raise ValueError("size string is empty")

    import re
    # Match a number (integer or decimal) followed by an optional unit (K, M, G, T, P, E) and an optional trailing 'B'
    match = re.fullmatch(r'(?P<num>[\d\.]+)\s*(?P<unit>[kKmMgGtTpPeE])?B?', size)
    if not match:
        raise ValueError(f"Invalid size format: {size!r}")

    num_str = match.group('num')
    unit = match.group('unit')
    try:
        num = float(num_str)
    except ValueError:
        raise ValueError(f"Invalid numeric value: {num_str!r}")

    factor = 1
    if unit:
        unit = unit.upper()
        if unit == 'K':
            factor = 10**3
        elif unit == 'M':
            factor = 10**6
        elif unit == 'G':
            factor = 10**9
        elif unit == 'T':
            factor = 10**12
        elif unit == 'P':
            factor = 10**15
        elif unit == 'E':
            factor = 10**18
        else:
            raise ValueError(f"Unknown unit: {unit!r}")

    return int(round(num * factor))

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    # Validate that dicts is an iterable
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError("The argument 'dicts' must be an iterable of dictionaries")

    result = {}
    for idx, d in enumerate(iterator):
        if not isinstance(d, dict):
            raise TypeError(f"Element at index {idx} is not a dictionary")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise TypeError(f"Value for key '{key}' in dictionary at index {idx} is not numeric")
            result[key] = result.get(key, 0) + value
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        if not isinstance(val, str):
            return False
        s = val.strip().lower()
        return s in {"none", "null", "nil"}
    except Exception:
        return False

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Validate input
    if parser is None:
        raise TypeError("parser must not be None")
    # argparse.ArgumentParser instances expose a _actions attribute
    if not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance")
    flags = []
    try:
        for action in parser._actions:
            # Each action may have an option_strings attribute listing its flags
            option_strings = getattr(action, "option_strings", None)
            if option_strings:
                flags.extend(option_strings)
    except Exception as exc:
        raise RuntimeError(f"Failed to extract flags from parser: {exc}") from exc
    return " ".join(flags)

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    try:
        return value.replace('.', arg)
    except Exception as exc:
        raise RuntimeError(f"Failed to replace dots: {exc}") from exc

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class type, got {type(cls).__name__}")
    result = set()
    try:
        for subclass in cls.__subclasses__():
            result.add(subclass)
            result.update(subclasses(subclass))
    except Exception as exc:
        raise RuntimeError(f"Error retrieving subclasses of {cls.__name__}") from exc
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate alphabet
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet contains duplicate characters")

    base = len(alphabet)
    char_to_value = {ch: i for i, ch in enumerate(alphabet)}

    # Empty string represents zero
    if string == "":
        return 0

    value = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' not found in alphabet")
        value = value * base + char_to_value[ch]
    return value

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        return os.uname().sysname == 'Darwin'
    except Exception:
        return False

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Remove leading or trailing single or double quotes
    return re.sub(r"^['\"]|['\"]$", "", name)

def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Import modules locally to avoid top-level imports
    import shlex
    import os
    import sys

    # Validate input
    if not isinstance(s, str):
        raise TypeError(f"Expected a string for 's', got {type(s).__name__}")

    # Resolve platform
    if platform == 'this':
        # Detect current platform
        if os.name == 'nt' or sys.platform.startswith('win'):
            platform = 0
        else:
            platform = 1
    if platform == 1:
        posix = True
    elif platform == 0:
        posix = False
    else:
        raise ValueError("platform must be 'this', 1 (POSIX), or 0 (Windows)")

    try:
        # Use shlex.split with appropriate posix flag
        return shlex.split(s, posix=posix)
    except Exception as exc:
        # Wrap any exception in a ValueError with context
        raise ValueError(f"Failed to split command line: {exc}") from exc

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq_str = frequency.strip()
    if freq_str.lower() == "always":
        return None
    parts = freq_str.split()
    if len(parts) != 2:
        raise ValueError(f"Cannot parse frequency: {frequency!r}")
    num_str, unit = parts
    try:
        num = float(num_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: {frequency!r}")
    unit = unit.lower()
    kwargs = {}
    if unit in ("day", "days"):
        kwargs["days"] = num
    elif unit in ("week", "weeks"):
        kwargs["weeks"] = num
    elif unit in ("hour", "hours"):
        kwargs["hours"] = num
    elif unit in ("minute", "minutes"):
        kwargs["minutes"] = num
    elif unit in ("second", "seconds"):
        kwargs["seconds"] = num
    else:
        raise ValueError(f"Unknown unit in frequency: {frequency!r}")
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    host = host.strip()
    # Direct string checks
    if host.lower() == "localhost":
        return True
    if host == "127.0.0.1" or host == "::1":
        return True
    try:
        # Resolve host to IP addresses
        for res in socket.getaddrinfo(host, None):
            ip = res[4][0]
            # IPv4 loopback
            if ":" not in ip:
                if ip.startswith("127."):
                    return True
            # IPv6 loopback
            else:
                if ip == "::1":
                    return True
    except socket.gaierror:
        # Host could not be resolved
        return False
    return False

def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    # Validate input
    if find_paths is None:
        raise TypeError("find_paths cannot be None")
    # Strings are iterable but should be treated as a single element
    if isinstance(find_paths, (str, bytes)):
        raise TypeError("find_paths must be an iterable of strings, not a single string")
    try:
        iterator = iter(find_paths)
    except TypeError:
        raise TypeError("find_paths must be an iterable of strings")

    result = []
    pattern_re = re.compile(r'^[a-z]+:.*$')
    for item in iterator:
        # Ensure the item is a string
        if not isinstance(item, str):
            try:
                item = str(item)
            except Exception as exc:
                raise TypeError(f"find_paths contains non-string item that cannot be converted: {item}") from exc

        # If the item already looks like a pattern (e.g., starts with a prefix and colon), keep it
        if pattern_re.match(item):
            result.append(item)
        else:
            # Escape any backslashes in the fragment to avoid unintended glob behavior
            fragment = item.replace("\\", "\\\\")
            result.append(f"sh:**/*{fragment}*/**")
    return result

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    """
    # Validate inputs
    if not isinstance(config_filename, str) or not config_filename:
        raise ValueError("config_filename must be a non-empty string")
    if not isinstance(rendered_config, str):
        raise ValueError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise ValueError("mode must be an integer")
    if not isinstance(overwrite, bool):
        raise ValueError("overwrite must be a boolean")

    # If file exists and overwrite is False, abort
    if os.path.exists(config_filename) and not overwrite:
        raise FileExistsError(f"File '{config_filename}' already exists and overwrite is False")

    # Ensure the directory exists
    dir_name = os.path.dirname(config_filename)
    if dir_name:
        try:
            os.makedirs(dir_name, exist_ok=True)
        except OSError as e:
            raise RuntimeError(f"Failed to create directories for '{config_filename}': {e}") from e

    # Write the configuration file
    try:
        with open(config_filename, "w", encoding="utf-8") as f:
            f.write(rendered_config)
        os.chmod(config_filename, mode)
    except OSError as e:
        raise RuntimeError(f"Failed to write configuration to '{config_filename}': {e}") from e
    return None

def oneline(script, seperator=" && "):
    """
    converts a script to one line command.
    THis is useful to run a single ssh command and pass a one line script.

    :param script:
    :return:
    """
    # Handle None input
    if script is None:
        return ""
    # If script is a list or tuple, join its elements into a string
    if isinstance(script, (list, tuple)):
        try:
            script = "\n".join(str(item) for item in script)
        except Exception:
            raise TypeError("script list elements must be convertible to string")
    # Ensure script is a string
    if not isinstance(script, str):
        try:
            script = str(script)
        except Exception:
            raise TypeError("script must be a string or convertible to string")
    # Ensure separator is a string
    if not isinstance(seperator, str):
        try:
            seperator = str(seperator)
        except Exception:
            seperator = " && "
    # Split into lines, strip whitespace, and filter out empty lines
    lines = [line.strip() for line in script.splitlines() if line.strip()]
    # Join the cleaned lines with the separator
    return seperator.join(lines)

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    # Validate input types
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a string")
    if not isinstance(strip, bool):
        raise TypeError("strip must be a boolean")

    # Optionally strip whitespace
    if strip:
        pattern = pattern.strip()

    # Escape regex special characters to treat the string literally
    escaped = re.escape(pattern)

    # Compile the escaped pattern and return it
    try:
        return re.compile(escaped)
    except re.error as e:
        raise ValueError(f"Invalid regex pattern: {e}") from e

def is_ipv4(target):
    """Test if IPv4 address or not"""
    try:
        addr = ipaddress.ip_address(target)
        return isinstance(addr, ipaddress.IPv4Address)
    except Exception:
        return False

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate shape
    if not isinstance(shape, (tuple, list)):
        raise TypeError("shape must be a tuple or list of integers")
    if not all(isinstance(s, int) and s >= 0 for s in shape):
        raise ValueError("shape must contain non-negative integers")

    # Validate dtype
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"Invalid dtype: {exc}") from exc

    # Create the array
    try:
        return np.empty(shape, dtype=dtype_obj)
    except Exception as exc:
        raise ValueError(f"Failed to create array with shape {shape} and dtype {dtype_obj}: {exc}") from exc

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        if x is None:
            raise ValueError("Input x cannot be None.")
        # Convert input to a NumPy array for vectorized operations
        arr = np.asarray(x)
        sigma = 0.1
        center = 0.2
        result = np.exp(-((arr - center) ** 2) / (2 * sigma ** 2))
        # Return a Python scalar if the input was a scalar
        if np.isscalar(x):
            return float(result)
        return result
    except Exception as e:
        raise ValueError(f"Invalid input for gaussian: {e}") from e

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        # Validate that `values` is an iterable of strings (but not a single string)
        if values is None:
            raise TypeError("values must be an iterable of strings, got None")
        if isinstance(values, (str, bytes)):
            raise TypeError("values must be an iterable of strings, got a single string")
        try:
            iterator = iter(values)
        except TypeError as exc:
            raise TypeError("values must be an iterable of strings") from exc

        # Ensure each element is a string
        for idx, v in enumerate(iterator):
            if not isinstance(v, str):
                raise ValueError(f"Bookmark value at index {idx} must be a string, got {type(v).__name__}")

        # Attempt to construct the Bookmarks instance
        try:
            return cls(values)
        except Exception as exc:
            raise ValueError(f"Failed to create Bookmarks from raw values: {exc}") from exc

