def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    else:
        # Remove the key after retrieving its value
        del self[key]
        return value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    try:
        # Ensure the cache has the expected attributes
        if not hasattr(self, "freq_map") or not hasattr(self, "key_to_val") or not hasattr(self, "key_to_freq"):
            raise AttributeError("Cache object missing required attributes for LFU operation.")

        # Determine the current minimum frequency
        min_freq = getattr(self, "min_freq", None)
        if min_freq is None:
            if not self.freq_map:
                raise KeyError("popitem(): dictionary is empty")

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Ensure the cache attribute exists and is dict-like
    if not hasattr(self, "cache"):
        raise AttributeError("The object has no 'cache' attribute")
    cache = getattr(self, "cache")
    if not isinstance(cache, dict):
        raise TypeError("'cache' attribute must be a dict or OrderedDict")
    if not cache:
        raise KeyError("popitem(): dictionary is empty")
    # Prefer OrderedDict's popitem(last=True) if available
    try:
        return cache.popitem(last=True)
    except TypeError:
        # Fallback for plain dict (Python 3.7+ preserves insertion order)
        return cache.popitem()

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    try:
        # Matches the keyword 'in' (case‑insensitive) followed by optional whitespace
        # and a parenthesized list of comma‑separated values. The list contents
        # are captured in a group for later extraction.
        return re.compile(r'\bin\s*\(([^)]*)\)', re.IGNORECASE)
    except re.error as exc:
        raise ValueError(f"Failed to compile in‑style regex: {exc}") from exc

def _create_converter(self) -> _converting._Converter:
    """
    Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
        converter = _converting._Converter()
    except NameError as e:
        # The _converting module or _Converter class is not available.
        raise ImportError("The required module or class '_converting._Converter' could not be found.") from e
    except Exception as e:
        # Any other exception during instantiation is wrapped in a RuntimeError.
        raise RuntimeError("Failed to create the parameter style converter.") from e

    # Optional sanity check: ensure the returned object is of the expected type.
    try:
        if not isinstance(converter, _converting._Converter):
            raise TypeError("Returned object is not an instance of _converting._Converter.")
    except NameError:
        # If the type cannot be checked due to missing module, skip the check.
        pass

    return converter

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        # Check for public message
        if getattr(request, "public", False):
            return True
        if isinstance(request, dict) and request.get("public", False):
            return True

        # Check for private message
        if getattr(request, "private", False):
            return True
        if isinstance(request, dict) and request.get("private", False):
            return True

        # Check for legacy payload
        if getattr(request, "legacy", False):
            return True
        if isinstance(request, dict) and request.get("legacy", False):
            return True

        # Additional heuristic: look for a payload that contains a Diaspora marker
        payload = getattr(request, "payload", None)
        if payload is None and isinstance(request, dict):
            payload = request.get("payload")
        if payload and isinstance(payload, dict) and payload.get("diaspora"):
            return True

        return False
    except Exception:
        # In case of any unexpected error, conservatively return False
        return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        if request is None:
            return False

        # Handle dictionary-like requests
        if isinstance(request, dict):
            keys = set(request.keys())
            # Common Matrix fields
            if "type" in keys:
                t = request.get("type")
                if isinstance(t, str) and t.startswith("m."):
                    return True
            if any(k in keys for k in ("room_id", "sender", "event_id")):
                return True
            return False

        # Handle object-like requests
        common_attrs = ("type", "content", "room_id", "sender", "event_id")
        for attr in common_attrs:
            if hasattr(request, attr):
                val = getattr(request, attr)
                if attr == "type" and isinstance(val, str) and val.startswith("m."):
                    return True
                if attr in ("room_id", "sender", "event_id") and val:
                    return True
        return False
    except Exception:
        # Any unexpected error should result in a safe False
        return False

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # Ensure the input is a string
    if not isinstance(tag, str):
        return False

    # Tag must not be empty
    if not tag:
        return False

    # Optional length constraint (e.g., max 30 characters)
    if len(tag) > 30:
        return False

    # Tag must not start or end with a hyphen
    if tag[0] == '-' or tag[-1] == '-':
        return False

    prev_hyphen = False
    for ch in tag:
        if ch == '-':
            # No consecutive hyphens
            if prev_hyphen:
                return False
            prev_hyphen = True
        else:
            # Only lowercase letters or digits allowed
            if not (ch.islower() or ch.isdigit()):
                return False
            prev_hyphen = False

    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        raise ValueError("node cannot be None")
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("node must be an XML element with iterable children") from exc

    result = {}
    for child in children:
        tag = getattr(child, "tag", None)
        if tag is None:
            continue
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic input validation
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if document_path is not None and not isinstance(document_path, str):
        raise TypeError("document_path must be a string if provided")

    # Ensure the URL has a scheme
    if not url.startswith(("http://", "https://")):
        raise ValueError("url must start with http:// or https://")

    # Normalize the base URL: strip trailing slash
    base_url = url.rstrip("/")

    # Determine the NodeInfo document path
    if document_path is None:
        nodeinfo_path = "/nodeinfo/2.0"
    else:
        # Ensure it starts with a slash
        nodeinfo_path = document_path if document_path.startswith("/") else "/" + document_path

    # Construct the full href
    href = f"{base_url}{nodeinfo_path}"

    # Build the .well-known document
    well_known = {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

    return well_known

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Validate input
    if not isinstance(document, str) or not document.strip():
        return {}

    # Try JSON first
    try:
        import json
        return json.loads(document)
    except Exception:
        pass

    # Fallback to XRD (XML) parsing
    try:
        import xml.etree.ElementTree as ET

        def _strip_ns(tag: str) -> str:
            return tag.split("}", 1)[-1] if "}" in tag else tag

        root = ET.fromstring(document)

        subject = None
        aliases: list[str] = []
        links: list[dict] = []

        for elem in root.iter():
            tag = _strip_ns(elem.tag)
            if tag == "Subject" and subject is None:
                subject = elem.text
            elif tag == "Alias":
                if elem.text:
                    aliases.append(elem.text)
            elif tag == "Link":
                link: dict = {}
                for attr in ("rel", "type", "href", "title"):
                    val = elem.get(attr)
                    if val:
                        link[attr] = val
                if link:
                    links.append(link)

        result: dict = {}
        if subject:
            result["subject"] = subject
        if aliases:
            result["aliases"] = aliases
        if links:
            result["links"] = links

        return result
    except Exception:
        # If parsing fails, return an empty dict
        return {}

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    import os
    import fnmatch

    # Validate settings_dirs
    if not hasattr(settings_dirs, "__iter__") or isinstance(settings_dirs, (str, bytes)):
        raise TypeError("settings_dirs must be an iterable of directory paths")

    # Normalize spec_option
    if spec_option is None or spec_option == "":
        patterns = ["*"]
    elif isinstance(spec_option, (list, tuple)):
        patterns = [p for p in spec_option if isinstance(p, str)]
        if not patterns:
            patterns = ["*"]
    elif isinstance(spec_option, str):
        patterns = [spec_option]
    else:
        raise TypeError("spec_option must be a string, list/tuple of strings, or None")

    result = []
    for dir_path in settings_dirs:
        if not isinstance(dir_path, (str, bytes)):
            continue  # skip invalid entries
        try:
            if not os.path.isdir(dir_path):
                continue  # skip non-directories
            for entry in os.listdir(dir_path):
                try:
                    if any(fnmatch.fnmatch(entry, pat) for pat in patterns):
                        full_path = os.path.join(dir_path, entry)
                        result.append(full_path)
                except Exception:
                    # Skip entries that cause errors during matching
                    continue
        except (OSError, PermissionError):
            # Skip directories that cannot be accessed
            continue
    return result

