def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        # Define the mandatory fields that must be present in the spec
        required_fields = {"name", "version", "description", "spec_version"}

        # If no content is provided, raise an exception
        if spec_content is None:
            raise IRValidatorException("Spec content is missing")

        # If the content is a string, attempt to parse it as YAML
        if isinstance(spec_content, str):
            try:
                import yaml
                spec_dict = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException(f"Failed to parse YAML content: {exc}") from exc
        elif isinstance(spec_content, dict):
            spec_dict = spec_content
        else:
            raise IRValidatorException(
                f"Unsupported spec_content type: {type(spec_content).__name__}"
            )

        # Ensure the parsed content is a dictionary
        if not isinstance(spec_dict, dict):
            raise IRValidatorException(
                f"Spec content must be a mapping, got {type(spec_dict).__name__}"
            )

        # Check for missing required fields
        missing = required_fields - spec_dict.keys()
        if missing:
            missing_str = ", ".join(sorted(missing))
            raise IRValidatorException(
                f"Missing required field(s) in spec: {missing_str}"
            )

        return spec_dict

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if not yaml_file:
        raise IRValidatorException("yaml_file must be provided")

    try:
        import yaml
    except Exception as exc:
        raise IRValidatorException(f"Failed to import yaml module: {exc}") from exc

    try:
        with open(yaml_file, "r", encoding="utf-8") as f:
            data = yaml.safe_load(f)
    except FileNotFoundError as exc:
        raise IRValidatorException(f"File not found: {yaml_file}") from exc
    except Exception as exc:
        raise IRValidatorException(f"Error reading YAML file '{yaml_file}': {exc}") from exc

    if data is None:
        data = {}

    # Determine required fields; subclasses may define REQUIRED_FIELDS
    required_fields = getattr(cls, "REQUIRED_FIELDS", [])
    if not isinstance(required_fields, (list, tuple, set)):
        raise IRValidatorException("REQUIRED_FIELDS must be a list, tuple, or set")

    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

    return data

def get_spec_defaults(self):
    """
    Resolve arguments' values from spec and other sources.

    Returns:
        dict: A mapping of argument names to their resolved default values.
    """
    resolved = {}
    try:
        spec = getattr(self, 'spec', None)
        if not isinstance(spec, dict):
            return resolved
        for arg, arg_spec in spec.items():
            default_val = None
            if isinstance(arg_spec, dict):
                # Primary default from spec
                default_val = arg_spec.get('default')
                # Override with config value if specified
                config_key = arg_spec.get('config')
                if config_key:
                    config = getattr(self, 'config', {})
                    if isinstance(config, dict):
                        config_val = config.get(config_key)
                        if config_val is not None:
                            default_val = config_val
            else:
                # If spec entry is not a dict, treat it as the default value
                default_val = arg_spec
            resolved[arg] = default_val
    except Exception:
        # In case of any unexpected error, return an empty dict
        resolved = {}
    return resolved

