def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Ensure arguments are dictionaries; treat None as empty dict
    if cli_args is None:
        cli_args = {}
    if answer_file_args is None:
        answer_file_args = {}
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Define a set of known deprecated argument names.
    # This set can be extended as needed.
    deprecated_args = {
        "--old-arg",
        "-o",
        "legacy",
        "deprecated",
        "old_option",
        "oldFlag",
        "oldFlagValue",
    }

    # Combine keys from both sources, ignoring non-string keys
    all_keys = set()
    for key in cli_args.keys():
        if isinstance(key, str):
            all_keys.add(key)
    for key in answer_file_args.keys():
        if isinstance(key, str):
            all_keys.add(key)

    # Track which deprecated arguments have been reported to avoid duplicate warnings
    reported = set()

    for key in all_keys:
        if key in deprecated_args and key not in reported:
            try:
                print(f"Warning: Argument '{key}' is deprecated and will be removed in future releases.")
            except Exception:
                # If printing fails for any reason, silently ignore to avoid breaking the flow
                pass
            reported.add(key)

    # No return value needed; method performs validation and prints warnings
    return None

def get_parser_option_specs(self, command_name):
        """Gets all the options for the specified command

        :param command_name: the command name (main, virsh, ospd, etc...)
        :return: the list of all command options
        """
        # Validate input
        if not isinstance(command_name, str):
            raise TypeError("command_name must be a string")

        # Ensure the parser has subparsers
        subparsers_action = None
        for action in getattr(self.parser, "_subparsers", [])._actions:
            if isinstance(action, type(self.parser._subparsers._actions[0])):
                subparsers_action = action
                break

        if subparsers_action is None:
            raise ValueError("No subparsers found in the parser")

        # Retrieve the subparser for the given command
        try:
            subparser = subparsers_action.choices[command_name]
        except KeyError:
            raise ValueError(f"Command '{command_name}' not found in parser subcommands")

        # Collect all option strings from the subparser
        option_specs = []
        for action in subparser._actions:
            # Skip positional arguments (no option strings)
            if getattr(action, "option_strings", None):
                option_specs.extend(action.option_strings)

        return option_specs

def get_silent_args(self, args):
    """
    list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    try:
        if args is None:
            return []

        silent = []

        # If args is a dictionary, consider keys with None or empty string values as silent
        if isinstance(args, dict):
            for key, value in args.items():
                if value is None or value == '':
                    silent.append(key)

        # If args is an iterable of strings (list, tuple, set), filter by naming convention
        elif isinstance(args, (list, tuple, set)):
            for item in args:
                if isinstance(item, str):
                    # Treat arguments starting with '_' or common silent flags as silent
                    if item.startswith('_') or item.lower() in {'quiet', 'silent', 'verbose', 'debug'}:
                        silent.append(item)

        # If args is a single string, apply the same naming convention
        elif isinstance(args, str):
            if args.startswith('_') or args.lower() in {'quiet', 'silent', 'verbose', 'debug'}:
                silent.append(args)

        return silent
    except Exception:
        # In case of any unexpected error, return an empty list to avoid breaking the caller
        return []

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Treat None as an empty set of arguments
    if args is None:
        args = {}
    # Ensure args is a mapping
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")
    # Retrieve the list of required argument names
    required = getattr(self, "required_args", None)
    if required is None:
        # No required arguments defined; nothing to validate
        return
    if not isinstance(required, (list, set, tuple)):
        raise TypeError(
            f"required_args must be a list, set, or tuple, got {type(required).__name__}"
        )
    # Find any missing required arguments
    missing = [name for name in required if name not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    # Validate inputs
    if not isinstance(options_spec, list):
        raise TypeError("options_spec must be a list of option specifications")
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of received arguments")

    required_names = set()

    for opt in options_spec:
        if not isinstance(opt, dict):
            continue  # skip malformed option spec
        name = opt.get("name")
        if not name:
            continue  # skip options without a name

        cond = opt.get("required_when")
        if cond is None:
            continue  # no conditional requirement

        try:
            if callable(cond):
                # If the condition is a callable, call it with args and command_name
                match = cond(args, command_name)
            else:
                # Assume the condition is a string expression; evaluate it safely
                # Provide a minimal namespace containing args and command_name
                match = eval(cond, {}, {"args": args, "command_name": command_name})
        except Exception:
            # If evaluation fails, treat the condition as not matched
            match = False

        if match:
            required_names.add(name)

    return list(required_names)

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
        # Default maximum length if not specified elsewhere
        default_max = getattr(self, 'default_max_length', 255)
        # Optional per-argument maximum lengths mapping
        per_arg_max = getattr(self, 'max_lengths', {})

        if args is None:
            return

        # Handle dictionary of arguments
        if isinstance(args, dict):
            for key, value in args.items():
                # Skip None values
                if value is None:
                    continue
                # Determine the maximum length for this key
                max_len = per_arg_max.get(key, default_max)
                # Only check types that have a length
                if isinstance(value, (str, list, tuple, set)):
                    if len(value) > max_len:
                        raise ValueError(
                            f"Argument '{key}' exceeds maximum length of {max_len}."
                        )
        # Handle list/tuple of arguments
        elif isinstance(args, (list, tuple)):
            for idx, value in enumerate(args):
                if value is None:
                    continue
                if isinstance(value, (str, list, tuple, set)):
                    if len(value) > default_max:
                        raise ValueError(
                            f"Argument at index {idx} exceeds maximum length of {default_max}."
                        )
        else:
            raise TypeError("args must be a dict or a list/tuple of arguments.")

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    try:
        # Basic validation of inputs
        if not isinstance(subcommand, str) or not subcommand:
            raise ValueError("subcommand must be a non-empty string")
        if not isinstance(type_name, str) or not type_name:
            raise ValueError("type_name must be a non-empty string")
        if not isinstance(option_name, str) or not option_name:
            raise ValueError("option_name must be a non-empty string")
        if spec_option is None:
            spec_option = {}
        if not isinstance(spec_option, dict):
            raise TypeError("spec_option must be a dictionary")

        # Construct a simple representation of the complex type
        complex_type = {
            "subcommand": subcommand,
            "type_name": type_name,
            "option_name": option_name,
            "spec": spec_option,
            "value": None  # placeholder for the actual value
        }

        return complex_type

    except Exception as exc:
        # Re-raise with additional context
        raise RuntimeError(
            f"Failed to create complex argument type for subcommand '{subcommand}', "
            f"type '{type_name}', option '{option_name}': {exc}"
        ) from exc

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    # Validate input dictionary
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    # No extra variables to merge
    if extra_vars is None:
        return vars_dict

    # Treat a single string as a single-item list
    if isinstance(extra_vars, str):
        extra_vars = [extra_vars]

    # Ensure the extra_vars is iterable
    try:
        iter(extra_vars)
    except TypeError:
        raise TypeError("extra_vars must be an iterable of strings")

    def _parse_value(val):
        """Parse a string value into a Python type."""
        if not isinstance(val, str):
            return val
        val = val.strip()
        # Strip surrounding quotes if present
        if len(val) >= 2 and ((val[0] == val[-1] == "'") or (val[0] == val[-1] == '"')):
            val = val[1:-1]
        lower = val.lower()
        if lower == "true":
            return True
        if lower == "false":
            return False
        if lower in ("null", "none"):
            return None
        # Try integer conversion
        try:
            return int(val)
        except ValueError:
            pass
        # Try float conversion
        try:
            return float(val)
        except ValueError:
            pass
        return val

    for item in extra_vars:
        if not isinstance(item, str):
            # Skip non-string items
            continue
        if "=" not in item:
            # Skip items that don't contain a key=value pair
            continue
        key, value = item.split("=", 1)
        key = key.strip()
        if not key:
            continue
        parsed_value = _parse_value(value)
        vars_dict[key] = parsed_value

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import os
    import json
    import subprocess
    import shlex

    # Validate playbook path
    if not isinstance(playbook_path, str) or not playbook_path:
        raise ValueError("playbook_path must be a non-empty string")
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Base command
    cmd = ["ansible-playbook", playbook_path]

    # Verbosity
    if verbose is not None:
        try:
            v = int(verbose)
            if v > 0:
                cmd.append("-" + "v" * v)
        except (TypeError, ValueError):
            raise ValueError("verbose must be an integer or None")

    # Extra vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise ValueError("extra_vars must be a dict")
        try:
            json_str = json.dumps(extra_vars)
        except (TypeError, ValueError) as e:
            raise ValueError(f"extra_vars could not be serialized to JSON: {e}")
        cmd.extend(["--extra-vars", json_str])

    # Additional ansible arguments
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise ValueError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if value is None:
                continue
            if isinstance(value, bool):
                if value:
                    cmd.append(f"--{key}")
                # skip if False
            else:
                cmd.append(f"--{key}={value}")

    # Logging (if available)
    if hasattr(ir_plugin, "log") and callable(ir_plugin.log):
        ir_plugin.log(f"Running ansible-playbook: {' '.join(shlex.quote(c) for c in cmd)}")

    # Environment: inherit from workspace if provided
    env = os.environ.copy()
    if hasattr(ir_workspace, "env") and isinstance(ir_workspace.env, dict):
        env.update(ir_workspace.env)

    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            env=env,
            check=False
        )
    except FileNotFoundError as e:
        raise RuntimeError("ansible-playbook executable not found") from e
    except Exception as e:
        raise RuntimeError(f"Failed to run ansible-playbook: {e}") from e

    # Raise error if playbook failed
    if result.returncode != 0:
        error_msg = (
            f"ansible-playbook failed with return code {result.returncode}\n"
            f"stdout:\n{result.stdout}\n"
            f"stderr:\n{result.stderr}"
        )
        raise RuntimeError(error_msg)

    return result

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """
    Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    # Ensure inputs are valid
    if cli_args is None:
        cli_args = []
    if not isinstance(cli_args, list):
        raise TypeError("cli_args must be a list of command line arguments")
    if vars_dict is None:
        vars_dict = {}
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    # Prepare the command
    try:
        import json
        import subprocess
    except Exception as exc:
        # If imports fail, log and return error
        if hasattr(ir_plugin, "logger"):
            ir_plugin.logger.error(f"Failed to import required modules: {exc}")
        else:
            print(f"Failed to import required modules: {exc}")
        return {"stdout": "", "stderr": str(exc), "returncode": -1}

    # Build the ansible-playbook command
    command = ["ansible-playbook"] + cli_args
    # Append extra-vars as JSON string
    try:
        extra_vars_json = json.dumps(vars_dict)
    except Exception as exc:
        if hasattr(ir_plugin, "logger"):
            ir_plugin.logger.error(f"Failed to serialize vars_dict to JSON: {exc}")
        else:
            print(f"Failed to serialize vars_dict to JSON: {exc}")
        return {"stdout": "", "stderr": str(exc), "returncode": -1}
    command += ["--extra-vars", extra_vars_json]

    # Determine working directory
    cwd = None
    try:
        cwd = getattr(ir_workspace, "path", None)
    except Exception:
        cwd = None
    if cwd is None:
        # Fallback to current directory
        cwd = ""

    # Execute the command
    try:
        result = subprocess.run(
            command,
            cwd=cwd,
            capture_output=True,
            text=True,
            check=False,
        )
        # Return a dictionary with relevant information
        return {
            "stdout": result.stdout,
            "stderr": result.stderr,
            "returncode": result.returncode,
        }
    except FileNotFoundError as fnf_err:
        # ansible-playbook not found
        err_msg = f"ansible-playbook command not found: {fnf_err}"
        if hasattr(ir_plugin, "logger"):
            ir_plugin.logger.error(err_msg)
        else:
            print(err_msg)
        return {"stdout": "", "stderr": err_msg, "returncode": -1}
    except Exception as exc:
        # General exception handling
        err_msg = f"Error running ansible-playbook: {exc}"
        if hasattr(ir_plugin, "logger"):
            ir_plugin.logger.error(err_msg)
        else:
            print(err_msg)
        return {"stdout": "", "stderr": err_msg, "returncode": -1}

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to correct types by modifying values_dict in place.

        By default all the values are strings. This method attempts to convert
        values to bool, int, float, or list of those types when appropriate.
        It is tolerant to conversion errors and leaves the original string
        unchanged if a conversion fails.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc.
        :param values_dict: The dictionary of arguments to be converted.
        """
        if not isinstance(values_dict, dict):
            raise TypeError("values_dict must be a dictionary")

        def _convert_value(val):
            """Helper to convert a single value."""
            if isinstance(val, str):
                lower = val.lower()
                # Boolean
                if lower == "true":
                    return True
                if lower == "false":
                    return False
                # Integer
                if val.isdigit() or (val.startswith("-") and val[1:].isdigit()):
                    try:
                        return int(val)
                    except ValueError:
                        pass
                # Float
                try:
                    f = float(val)
                    # Only treat as float if it contains a decimal point or exponent
                    if "." in val or "e" in val.lower():
                        return f
                except ValueError:
                    pass
                # List (comma separated)
                if "," in val:
                    parts = [p.strip() for p in val.split(",")]
                    return [_convert_value(p) for p in parts]
                # Default: keep string
                return val
            elif isinstance(val, list):
                return [_convert_value(item) for item in val]
            else:
                return val

        for key, val in list(values_dict.items()):
            try:
                values_dict[key] = _convert_value(val)
            except Exception:
                # If any unexpected error occurs, keep the original value
                values_dict[key] = val

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    if not isinstance(plugin_dir, str):
        raise TypeError("plugin_dir must be a string path")
    if not os.path.isdir(plugin_dir):
        raise ValueError(f"plugin_dir '{plugin_dir}' is not a directory")

    # Find the plugin spec file (support common names)
    spec_file = None
    for name in ("plugin.yaml", "plugin.yml", "plugin.json"):
        path = os.path.join(plugin_dir, name)
        if os.path.isfile(path):
            spec_file = path
            break
    if spec_file is None:
        raise FileNotFoundError("No plugin spec file found in directory")

    # Load the spec file
    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            if spec_file.endswith((".yaml", ".yml")):
                if yaml is None:
                    raise ImportError("PyYAML is required to parse YAML files")
                data = yaml.safe_load(f)
            else:
                data = json.load(f)
    except Exception as exc:
        raise ValueError(f"Failed to load plugin spec: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError("Plugin spec must be a dictionary at the top level")

    # Helper to flatten nested structures
    def _flatten(d, parent_key=""):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key))
            elif isinstance(v, list):
                for idx, item in enumerate(v):
                    list_key = f"{new_key}[{idx}]"
                    if isinstance(item, dict):
                        items.update(_flatten(item, list_key))
                    else:
                        items[list_key] = item
            else:
                items[new_key] = v
        return items

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        import os
        env_var = 'CONFIG_PATH'
        if env_var not in os.environ:
            # Default to a config file named 'config.yaml' in the current working directory
            default_path = os.path.join(os.getcwd(), 'config.yaml')
            os.environ[env_var] = default_path
    except Exception as e:
        raise RuntimeError(f"Failed to inject config environment variable: {e}") from e
